 } catch (error: unknown) {
 console.error('Connection init error:', error)
 const err = error as { response?: { data?: { error?: string } }; message?: string }
 setError(
 '❌ Failed to initialize connection: ' +
 (err.response?.data?.error || err.message || String(error))
 )
 setLoading(false)
 return
 }

 const params = new URLSearchParams({
 response_type: 'code',
 client_id: credentials.client_id,
 client_secret: credentials.client_secret,
 redirect_uri: credentials.redirect_uri,
 prompt: 'login',
 })

 const authorizationUrl = `${DEFAULT_SF_LOGIN_URL}/authorize?${params.toString()}`
 console.log(`authorizationUrl: ${authorizationUrl}`)
 window.location.href = authorizationUrl
 }

 const handleDisconnect = async () => {
 if (!confirm('Are you sure you want to disconnect?')) {
 return
 }

 try {
 await axios.post(
 `${apiBaseUrl}/connection/disconnect`,
 {},
 {
 headers: {
 Accept: 'application/json',
 'X-UserToken': userToken(),
 },
 }
 )
 } catch (error: unknown) {
 const err = error as { response?: { data?: { error?: string } }; message?: string }
 console.warn('Disconnect error:', err?.response?.data?.error || err.message)
 }

 localStorage.removeItem('salesforce_connection_id')

 onAuthenticationChange?.(false, null)
 window.location.reload()
 }

 if (isAuthenticated) {
 return (
 <div>
 <h2>Salesforce Connection</h2>
 <div className="connection-info">
 <h3>✅ Connected to Salesforce</h3>
 {connectionInfo ? (
 <pre className="connection-info-json">
 {typeof connectionInfo === 'string'
 ? connectionInfo
 : JSON.stringify(connectionInfo, null, 2)}
 </pre>
 ) : null}
 </div>
 <Button variant="danger" onClick={handleDisconnect} className="btn-disconnect">
 Disconnect
 </Button>
 </div>
 )
 }

 return (
 <div>
 <h2>Connect to Salesforce</h2>
 {error && (
 <div className={`alert ${error.startsWith('✅') ? 'alert-success' : 'alert-error'}`}>
 {error}
 </div>
 )}
 <div>
 <div className="form-group">
 <label htmlFor="client_id">Client ID (Consumer Key) *</label>
 <input
 type="text"
 id="client_id"
 value={credentials.client_id}
 onChange={(e) => setCredentials({ ...credentials, client_id: e.target.value })}
 placeholder="Enter your Salesforce Connected App Client ID"
 required
 />
 </div>
 <div className="form-group">
 <label htmlFor="client_secret">Client Secret (Consumer Secret) *</label>
 <input
 type="password"
 id="client_secret"
 value={credentials.client_secret}
 onChange={(e) => setCredentials({ ...credentials, client_secret: e.target.value })}
 placeholder="Enter your Salesforce Connected App Client Secret"
 required
 />
 </div>
 <div className="form-group">
 <label htmlFor="redirect_uri">Redirect URI *</label>
 <input
 type="text"
 id="redirect_uri"
 value={credentials.redirect_uri}
 onChange={(e) => setCredentials({ ...credentials, redirect_uri: e.target.value })}
 placeholder="Enter your redirect URI. This must match the Callback URL configured in your Salesforce Connected App"
 required
 />
 </div>
 <Button variant="success" onClick={handleLogin} disabled={loading} loading={loading}>
 Connect
 </Button>
 </div>
 </div>
 )
}
","import React, { useMemo, useState } from 'react';
import '../app.css';
import './EditConfigurationModal.css';
import Button from './ui/Button';

export default function EditConfigurationModal({
 availableTaskTypes,
 pendingTaskTypes,
 setPendingTaskTypes,
 loading,
 onSave,
 onCancel
}) {
 const [searchQuery, setSearchQuery] = useState('');

 const normalizedQuery = searchQuery.trim().toLowerCase();

 const filteredTaskTypes = useMemo(() => {
 if (!normalizedQuery) {
 return availableTaskTypes;
 }

 return availableTaskTypes.filter((taskType) => {
 const label = (taskType.label || '').toLowerCase();
 const name = (taskType.name || '').toLowerCase();

 return label.includes(normalizedQuery) || name.includes(normalizedQuery);
 });
 }, [availableTaskTypes, normalizedQuery]);

 const togglePendingTaskType = (taskType) => {
 const isSelected = pendingTaskTypes.some(pt => pt.table_name === taskType.name);

 if (isSelected) {
 setPendingTaskTypes(pendingTaskTypes.filter(pt => pt.table_name !== taskType.name));
 } else {
 setPendingTaskTypes([...pendingTaskTypes, {
 table_name: taskType.name,
 table_label: taskType.label
 }]);
 }
 };

 const toggleSelectAll = () => {
 const allSelected = pendingTaskTypes.length === availableTaskTypes.length;

 if (allSelected) {
 setPendingTaskTypes([]);
 } else {
 const allTaskTypes = availableTaskTypes.map(taskType => ({
 table_name: taskType.name,
 table_label: taskType.label
 }));
 setPendingTaskTypes(allTaskTypes);
 }
 };

 const isAllSelected = pendingTaskTypes.length === availableTaskTypes.length && availableTaskTypes.length > 0;
 const hasNoMatches = filteredTaskTypes.length === 0;

 const handleSearchChange = (event) => {
 setSearchQuery(event.target.value);
 };

 const handleClearSearch = () => {
 setSearchQuery('');
 };

 return (
 <div className="dialog-overlay">
 <div className="dialog-content">
 <div className="dialog-header">
 <h3>✏️ Edit Task Types Configuration</h3>
 <button className="dialog-close" onClick={onCancel} aria-label="Close">
 ✕
 </button>
 </div>
 <p className="dialog-description">
 Select task types to synchronize with Salesforce.
 Selected types will be monitored for Create, Update, and Delete operations.
 </p>

 <div className="task-types-selector">
 <div className="select-all-container">
 <div className="select-all-search-row">
 <label className="select-all-label">
 <input
 type="checkbox"
 checked={isAllSelected}
 onChange={toggleSelectAll}
 className="select-all-checkbox"
 />
 <span>{isAllSelected ? 'Unselect all' : 'Select all'}</span>
 </label>

 <div className="task-search-wrapper">
 <input
 type="text"
 value={searchQuery}
 onChange={handleSearchChange}
 placeholder="Search task types..."
 className="task-search-input"
 aria-label="Search task types"
 />
 <button
 type="button"
 className="task-search-clear"
 onClick={handleClearSearch}
 disabled={!searchQuery}
 >
 Clear
 </button>
 </div>
 </div>
 </div>
 <h4>All Task Types:</h4>
 <div className="task-types-list-container">
 {hasNoMatches ? (
 <div className="task-types-empty-state">
 No task types match “{searchQuery}”
 </div>
 ) : (
 filteredTaskTypes.map((taskType) => {
 const isSelected = pendingTaskTypes.some(pt => pt.table_name === taskType.name);
 return (
 <div
 key={taskType.name}
 onClick={() => togglePendingTaskType(taskType)}
 className={`task-type-item ${isSelected ? 'selected' : ''}`}
 >
 <input
 type="checkbox"
 checked={isSelected}
 onChange={() => { }}
 className="task-type-checkbox"
 />
 <div>
 <strong>{taskType.label}</strong>
 <br />
 <small className="settings-description">
 Table: {taskType.name}
 </small>
 </div>
 </div>
 );
 })
 )}
 </div>
 </div>

 {pendingTaskTypes.length > 0 && (
 <div className="pending-selection">
 <strong>Selected ({pendingTaskTypes.length}):</strong>
 <div className="pending-selection-list">
 {pendingTaskTypes.map(pt => pt.table_label).join(', ')}
 </div>
 </div>
 )}

 <div className="dialog-actions">
 <Button
 variant="secondary"
 onClick={onCancel}
 >
 Cancel
 </Button>
 <Button
 variant="success"
 onClick={onSave}
 disabled={loading}
 loading={loading}
 >
 Save
 </Button>
 </div>
 </div>
 </div>
 );
}

