","import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react'
import axios from 'axios'

const TaskConfigContext = createContext()
const baseUrl = "/api/x_1955226_peeklo_1/x_1955226_peeklo_1_salesforce_integratio";

export function TaskConfigProvider({ isAuthenticated, children }) {
 const [availableTaskTypes, setAvailableTaskTypes] = useState([])
 const [selectedTaskTypes, setSelectedTaskTypes] = useState([])
 const [isLoading, setIsLoading] = useState(false)
 const [error, setError] = useState('')
 const hasLoadedRef = useRef(false)

 const fetchTaskData = useCallback(
 async (force = false) => {
 if (!isAuthenticated) {
 return
 }
 if (hasLoadedRef.current && !force) {
 return
 }

 setIsLoading(true)
 setError('')

 try {
 const headers = {
 Accept: 'application/json',
 'X-UserToken': window.g_ck
 }
 const [typesResponse, configResponse] = await Promise.all([
 axios.get(`${baseUrl}/task-types`, { headers }),
 axios.get(`${baseUrl}/task-type-config`, { headers })
 ])
 setAvailableTaskTypes(typesResponse.data.result.taskTypes || [])
 setSelectedTaskTypes(configResponse.data.result.task_types || [])
 hasLoadedRef.current = true
 } catch (err) {
 setError(err.response?.data?.error || err.message || 'Failed to load configuration')
 } finally {
 setIsLoading(false)
 }
 },
 [isAuthenticated]
 )

 useEffect(() => {
 if (!isAuthenticated) {
 setAvailableTaskTypes([])
 setSelectedTaskTypes([])
 setIsLoading(false)
 setError('')
 hasLoadedRef.current = false
 return
 }
 fetchTaskData()
 }, [isAuthenticated, fetchTaskData])

 const refreshTaskData = useCallback(() => fetchTaskData(true), [fetchTaskData])

 const saveTaskTypes = useCallback(async (taskTypes) => {
 try {
 await axios.put(
 `${baseUrl}/task-type-config`,
 { task_types: taskTypes },
 {
 headers: {
 'Content-Type': 'application/json',
 Accept: 'application/json',
 'X-UserToken': window.g_ck
 }
 }
 )
 setSelectedTaskTypes([...taskTypes])
 hasLoadedRef.current = true
 return { success: true }
 } catch (err) {
 const message = err.response?.data?.error || err.message || 'Failed to save configuration'
 return { success: false, error: message }
 }
 }, [])

 const value = {
 availableTaskTypes,
 selectedTaskTypes,
 isLoading,
 error,
 refreshTaskData,
 saveTaskTypes,
 setError
 }

 return <TaskConfigContext.Provider value={value}>{children}</TaskConfigContext.Provider>
}

export function useTaskConfig() {
 const context = useContext(TaskConfigContext)
 if (!context) {
 throw new Error('useTaskConfig must be used within a TaskConfigProvider')
 }
 return context
}

","import React, { useState } from 'react';
import '../app.css';
import './SettingsTab.css';
import EditConfigurationModal from './EditConfigurationModal.jsx';
import Button from './ui/Button';
import LoadingSpinner from './ui/LoadingSpinner.jsx';
import { useTaskConfig } from '../context/TaskConfigContext.jsx';

export default function SettingsTab({ isAuthenticated }) {
 const {
 availableTaskTypes = [],
 selectedTaskTypes = [],
 isLoading,
 error: contextError,
 saveTaskTypes
 } = useTaskConfig();
 const [showAddDialog, setShowAddDialog] = useState(false);
 const [pendingTaskTypes, setPendingTaskTypes] = useState([]);
 const [statusMessage, setStatusMessage] = useState('');
 const [isSaving, setIsSaving] = useState(false);

 const startEditTaskTypes = () => {
 setPendingTaskTypes([...(selectedTaskTypes || [])]);
 setShowAddDialog(true);
 setStatusMessage('');
 };

 const handleSaveSelectedTaskTypes = async () => {
 setIsSaving(true);
 setStatusMessage('');

 const result = await saveTaskTypes(pendingTaskTypes);

 setIsSaving(false);

 if (result.success) {
 setShowAddDialog(false);
 setPendingTaskTypes([]);
 setStatusMessage('✅ Task types configuration saved successfully!');
 setTimeout(() => setStatusMessage(''), 3000);
 } else {
 setStatusMessage('❌ ' + (result.error || 'Failed to save configuration'));
 }
 };

 const cancelAddDialog = () => {
 setShowAddDialog(false);
 setPendingTaskTypes([]);
 setStatusMessage('');
 };

 if (!isAuthenticated) {
 return (
 <div className="alert alert-warning">
 <h3>🔐 Connection Required</h3>
 <p>Please connect to Salesforce first in the Connection tab to configure task type synchronization.</p>
 </div>
 );
 }


 return (
 <div>
 <div className="settings-header">
 <div>
 <h2>📋 Task Type Configuration</h2>
 <p>Configure which ServiceNow task types (tables) should be synchronized with Salesforce.</p>
 </div>
 </div>

 {isLoading ? (
 <div className="loading">
 <LoadingSpinner size="xlarge" />
 </div>
 ) : (
 <div className="settings-section">
 <div className="settings-section-header">
 <h3>📌 Selected Task Types for synchronization</h3>
 <Button
 variant="primary"
 onClick={startEditTaskTypes}
 disabled={isLoading || isSaving}
 title="Edit task types configuration"
 >
 ✏️ Edit
 </Button>
 </div>

 {(selectedTaskTypes || []).length > 0 ? (
 <div className="selected-task-types-container">
 <div className="task-types-list">
 {selectedTaskTypes.map((taskType) => (
 <div
 key={taskType.table_name}
 className="task-type-chip"
 >
 <span className="task-type-label">
 <strong>{taskType.table_label}</strong>
 <small className="task-type-name">
 ({taskType.table_name})
 </small>
 </span>
 </div>
 ))}
 </div>
 </div>
 ) : (
 <div className="alert alert-info">
 <p>📋 You haven't added task types for synchronization yet.</p>
 <p>Click "Edit" to configure which ServiceNow task tables should sync with Salesforce.</p>
 </div>
 )}

 {contextError && (
 <div className="alert alert-error alert-error-top-margin">
 {contextError}
 </div>
 )}

 {statusMessage && !statusMessage.startsWith('✅') && (
 <div className="alert alert-error alert-error-top-margin">
 {statusMessage}
 </div>
 )}
 </div>
 )}

 {statusMessage && statusMessage.startsWith('✅') && (
 <div className="alert alert-success">
 {statusMessage}
 </div>
 )}

 {showAddDialog && (
 <EditConfigurationModal
 availableTaskTypes={availableTaskTypes}
 pendingTaskTypes={pendingTaskTypes}
 setPendingTaskTypes={setPendingTaskTypes}
 loading={isSaving}
 onSave={handleSaveSelectedTaskTypes}
 onCancel={cancelAddDialog}
 />
 )}
 </div>
 );
